void __cdecl BattleFx_RamuhSpawnCameraScript(void *script, void *matrix, int actorSlot)
{
    BattleFxRamuhCameraTask *task;

    task = (BattleFxRamuhCameraTask *)BATTLE_NEW_TASK_SLOT(BattleFx_RamuhRunCameraScript);
    task->cameraScript = (int)script;
    task->matrix = (int)matrix;
    task->actorSlot = actorSlot;
}

