void __cdecl BattleFx_SummonRamuhSetCameraShakeAmplitude(int amplitude)
{
    if (amplitude != 0) {
        if (g_BattleSummonRamuhTargetMask == 0) {
            g_BattleSummonRamuhTargetMask = (BattleFxRamuhCameraShakeSlot *)BATTLE_NEW_TASK_SLOT(BattleFx_SummonRamuhCameraShakeTask);
        }
        g_BattleSummonRamuhTargetMask->shakeOffset = amplitude;
    } else if (g_BattleSummonRamuhTargetMask != 0) {
        g_BattleSummonRamuhTargetMask->shakeOffset = 0xFFFF;
    }
}

/*
 * Updates decaying camera shake displacement for Ramuh.
 */
// FUNCTION: FF7 0x00598846
void __cdecl BattleFx_SummonRamuhCameraShakeTask(void)
{
    BattleFxRamuhCameraShakeSlot *task;

    task = (BattleFxRamuhCameraShakeSlot *)BATTLE_CURRENT_TASK_SLOT;
    if ((task->frameCount & 1) != 0) {
        g_BattleCameraPosition.cameraPosX += task->shakeOffset;
        g_BattleCameraFocalPoint.focalPointX += task->shakeOffset;
    } else {
        g_BattleCameraPosition.cameraPosX -= task->shakeOffset;
        g_BattleCameraFocalPoint.focalPointX -= task->shakeOffset;
    }
    if (g_BattleIsPaused == 0) {
        (task->frameCount)++;
    }
}

