/*
 * Draws PSX sprite records for Ramuh lightning effects.
 */
// FUNCTION: FF7 0x00598b0a
int __cdecl BattleFx_SummonRamuhDrawPsxSpriteRecords(BattleFxRamuhPsxSpriteHeader *header, int orderingTable, int depthShift, int packetCursor)
{
    int flags;
    int val;
    short width;
    short h;
    BattleFxRamuhSpriteRecord *pRecord;
    BattleFxRamuhSpriteBlock *blockPointer;
    int index;
    int entryCount;
    int padField; /* Unreferenced stack padding preserved for VC5 /Od frame size (see lib/codegen.h). */
    BattleFxRamuhSpritePacket *packet;
    int depthOut;

    pRecord = (BattleFxRamuhSpriteRecord *)Gfx_GetPsxScratchpadPtr(0xC0);
    packet = (BattleFxRamuhSpritePacket *)Gfx_GetPsxPacketScratchPtr();
    blockPointer = (BattleFxRamuhSpriteBlock *)(header->blockOffset + 8);
    for (index = 0; index < header->recordCount; index++) {
        blockPointer = (BattleFxRamuhSpriteBlock *)((char *)blockPointer + blockPointer->entryCount * 0xA * 2 + 4);
    }
    entryCount = blockPointer->entryCount;
    blockPointer = (BattleFxRamuhSpriteBlock *)((char *)blockPointer + 4);
    for (index = 0; index < entryCount; index++) {
        width = blockPointer->widthPair & 0xFF;
        h = blockPointer->heightPair & 0xFF;
        pRecord->startX = blockPointer->posX << 3;
        pRecord->posX = pRecord->startX;
        pRecord->endX = blockPointer->posX + width << 3;
        pRecord->targetX = pRecord->endX;
        pRecord->startY = blockPointer->posY << 3;
        pRecord->posY = pRecord->startY;
        pRecord->endY = blockPointer->posY + h << 3;
        pRecord->targetY = pRecord->endY;
        pRecord->vertex3Z = 0;
        pRecord->vertex2Z = 0;
        pRecord->vertex1Z = 0;
        pRecord->posZ = 0;
        depthOut = Gfx_TransformQuadReturnDepth(pRecord, (SVECTOR *)((int)pRecord + 8), (SVECTOR *)((int)pRecord + 0x10), (SVECTOR *)((int)pRecord + 0x18), &val, &flags);
        if ((flags & 0x60000) == 0) {
            packet->packetTag = 0x9000000;
            packet->colorWord = header->colorWord;
            packet->clut = blockPointer->clut;
            packet->tpage = blockPointer->tpage;
            flags = blockPointer->flags;
            if ((flags & 0x200) != 0) {
                width = blockPointer->widthPair >> 8 & 0xFF;
                h = blockPointer->heightPair >> 8 & 0xFF;
            }
            if ((flags & 1) != 0) {
                packet->u0 = blockPointer->texU + width + -1;
                packet->packetU0 = packet->u0;
                packet->u1 = (char)blockPointer->texU;
                packet->packetU1 = packet->u1;
            } else {
                packet->u0 = (char)blockPointer->texU;
                packet->packetU0 = packet->u0;
                packet->u1 = blockPointer->texU + width;
                packet->packetU1 = packet->u1;
            }
            if ((flags & 2) != 0) {
                packet->v0 = blockPointer->texV + h + -1;
                packet->packetV0 = packet->v0;
                packet->v1 = (char)blockPointer->texV;
                packet->packetV1 = packet->v1;
            } else {
                packet->v0 = (char)blockPointer->texV;
                packet->packetV0 = packet->v0;
                packet->v1 = blockPointer->texV + h;
                packet->packetV1 = packet->v1;
            }
            Gfx_DrawPsxPrimitive(packet);
        }
        blockPointer++;
    }
    return (int)packet;
}

